insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"c2c0fdd4-3535-4677-af80-cf4a791911e6","control_id":"O-PEN-005","version":1,"effective_from":"2024-11-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Identify demands for FY 2017-18 to 2019-20 under Section 73 eligible for waiver of interest and penalty on payment of tax, and ensure conditions are met.","law_refs":["CGST-ACT-S128A","CGST-ACT-S73"],"required_data":["drc03","electronic_liability_register","challans"],"procedure":"1. List notices/orders for FY 2017-18 to 2019-20 under Section 73.\\n2. Verify payment of full tax demanded by the notified date and filing of waiver application in the prescribed form.\\n3. Verify withdrawal of appeals where required.","automation":null,"expected_result":"Eligible cases availed waiver.","exception_conditions":"Eligible cases missed; partial payment; Section 74 cases mistakenly included.","risk_level":"medium","exposure_basis":"Interest and penalty saved/forgone.","evidence_required":["Waiver applications","Payment evidence"],"corrective_action":"Complete waiver procedures or document reasons for not availing.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.723165+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"2cfdf8a3-0412-4aa7-878b-0464fcd090b0","control_id":"O-PEN-006","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure audit-identified liabilities for pre-2024-25 periods are paid with interest before SCN under Section 73(5), and for later periods under Section 74A provisions, to minimise penalty.","law_refs":["CGST-ACT-S73","CGST-ACT-S74A","CGST-RULE-142"],"required_data":["drc03","electronic_cash_ledger"],"procedure":"1. List audit observations quantified as payable.\\n2. Verify DRC-03 payment with interest and intimation to the officer.\\n3. Track acknowledgement and closure.","automation":null,"expected_result":"Timely voluntary payments with interest.","exception_conditions":"Payments without interest; no intimation.","risk_level":"low","exposure_basis":"Penalty avoided if paid before notice (non-fraud).","evidence_required":["DRC-03 records"],"corrective_action":"Pay with interest and file intimation.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.726907+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"63004e28-d098-47c6-8b8e-98b3b245450f","control_id":"P-LIT-001","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure every notice, intimation and order issued on the GST portal (including the ''Additional Notices and Orders'' tab), by e-mail or physically is captured, assigned and tracked to closure.","law_refs":["CGST-ACT-S75","CGST-RULE-142","CGST-ACT-S61"],"required_data":["electronic_liability_register"],"procedure":"1. For each GSTIN, review the portal ''Notices and Orders'', ''Additional Notices and Orders'' and ''View Additional Notices'' sections, and the registered e-mail inbox, for the audit period and up to the audit date.\\n2. Compile a master list with reference number, form (ASMT-10, ADT-01, DRC-01A, DRC-01, DRC-07, REG-17, RFD-08 etc.), period, amount, issue date and due date.\\n3. Compare with the internal litigation/notice register and identify omissions.\\n4. Identify any ex parte orders (DRC-07) and the reason (non-receipt, non-response).\\n5. Confirm that the electronic liability register Part II reflects confirmed demands.","automation":null,"expected_result":"Internal register is complete and every item has an owner, due date and status.","exception_conditions":"Notices under ''Additional Notices'' not monitored; ex parte orders; demands in Part II not in register.","risk_level":"high","exposure_basis":"Ex parte confirmation of tax + interest + penalty; loss of appeal window u/s 107 if communication date missed; recovery proceedings.","evidence_required":["Portal screenshots per GSTIN","Notice register","Liability register Part II"],"corrective_action":"Update register, assign owners, seek rectification/appeal for ex parte orders, and institute weekly portal monitoring with escalation.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.730036+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"d441f556-e47c-482e-8bcf-d16d6696a1d0","control_id":"P-LIT-002","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure discrepancies communicated in ASMT-10 are answered in ASMT-11 within time with reconciliations, and that accepted liabilities are paid with interest.","law_refs":["CGST-ACT-S61","CGST-RULE-142"],"required_data":["gstr1","gstr3b","gstr2b","gstr9","drc03"],"procedure":"1. List ASMT-10 notices and categorise discrepancies (GSTR-1 vs 3B, 2A/2B vs 3B ITC, e-way bill vs returns, RCM, TDS/TCS).\\n2. For each, prepare a reconciliation linking to the relevant control results (B-OUT-002, C-ITC-001, G-EWB-001).\\n3. Verify ASMT-11 filed within the time allowed and payment via DRC-03 for admitted amounts.\\n4. Track whether ASMT-12 (closure) has been issued or the matter has escalated to SCN.","automation":null,"expected_result":"All scrutiny notices answered with reconciliations; admitted amounts paid with interest.","exception_conditions":"No reply; generic replies without reconciliation; admitted amounts unpaid.","risk_level":"medium","exposure_basis":"Escalation to SCN u/s 73/74/74A with tax, interest and penalty.","evidence_required":["ASMT-10, ASMT-11, ASMT-12 copies","Supporting reconciliations","DRC-03"],"corrective_action":"File comprehensive replies, pay admitted dues with interest, and seek closure orders.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.733517+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"82eea144-0c1b-4954-89ca-bcc3c9895b8a","control_id":"P-LIT-003","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure the entity is audit-ready and that audit paras are tracked from ADT-01 through ADT-02 and any resulting SCN.","law_refs":["CGST-ACT-S65","CGST-ACT-S73","CGST-ACT-S74A"],"required_data":["gstr9","gstr9c","trial_balance","drc03"],"procedure":"1. List ADT-01 notices, periods covered and documents requested.\\n2. Prepare standard audit pack: financial statements, GSTR-9/9C, reconciliations, ITC registers, RCM workings, export/refund files.\\n3. Track each para: accepted and paid (DRC-03 with interest), contested with written submission, or pending.\\n4. Verify ADT-02 issued and whether SCN followed for contested paras within limitation.","automation":null,"expected_result":"Audits closed with documented positions; accepted paras paid with interest.","exception_conditions":"Paras accepted without technical review; payments without interest; contested paras without submissions.","risk_level":"medium","exposure_basis":"Tax + interest on accepted paras; contested paras become SCN exposure.","evidence_required":["ADT-01/ADT-02","Para-wise tracker","Submissions"],"corrective_action":"Maintain a standard audit pack and para tracker; obtain technical review before accepting paras.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.736841+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"72af00f9-50f8-48a6-b5ad-beb399b8f9bd","control_id":"P-LIT-004","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure SCNs are answered on merits and on jurisdictional grounds: correct section for the period (73/74 for FY up to 2023-24; 74A for FY 2024-25 onwards), limitation, pre-SCN consultation, and quantification.","law_refs":["CGST-ACT-S73","CGST-ACT-S74","CGST-ACT-S74A","CGST-ACT-S75","CGST-RULE-142"],"required_data":["electronic_liability_register","drc03"],"procedure":"1. For each SCN, verify the provision invoked matches the financial year and nature of allegation.\\n2. Verify the notice was issued within limitation computed from the due date of the annual return (see O-LIM-004) and that invocation of extended period (Section 74) is supported by specific allegations of fraud/suppression.\\n3. Verify DRC-01A/pre-SCN consultation where applicable and that the demand does not exceed the notice.\\n4. Prepare reply (DRC-06) on merits with documentary support; request personal hearing under Section 75(4).\\n5. Evaluate option of payment within 30 days of SCN (reduced penalty) for weak positions.","automation":null,"expected_result":"Timely, complete replies covering jurisdiction, limitation and merits.","exception_conditions":"Reply not filed; wrong section unchallenged; extended period accepted without contest.","risk_level":"high","exposure_basis":"Tax + interest + penalty as proposed in SCN (100% penalty in fraud cases).","evidence_required":["SCN","DRC-06 reply","Hearing records"],"corrective_action":"File replies within time, attend hearings, and settle weak issues early to minimise penalty.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.73985+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"c2778d3c-5143-47d9-a99a-c97361259165","control_id":"P-LIT-005","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure appeals against adverse orders are filed within three months of communication (plus condonable one month) with correct pre-deposit.","law_refs":["CGST-ACT-S107","CGST-RULE-142"],"required_data":["electronic_liability_register","drc03","electronic_cash_ledger"],"procedure":"1. List all adverse orders (DRC-07, RFD-06 rejections, REG cancellations) with date of communication.\\n2. Compute appeal due dates and condonation window.\\n3. Verify pre-deposit (admitted tax + 10% of disputed tax, within statutory cap) paid and linked to the appeal (APL-01).\\n4. Confirm stay of recovery and that the liability register reflects the stay.\\n5. Track hearing dates and outcomes, and the availability of the Appellate Tribunal for second appeals.","automation":null,"expected_result":"All appeals filed in time with pre-deposit; recoveries stayed.","exception_conditions":"Time-barred appeals; pre-deposit paid but not linked; recovery initiated despite appeal.","risk_level":"high","exposure_basis":"Order becomes final; recovery of full demand including interest and penalty.","evidence_required":["Orders","APL-01 acknowledgements","Pre-deposit challans"],"corrective_action":"File appeals immediately, link pre-deposits, and request recovery stay updates on portal.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.742615+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"dec86b87-8f09-4f39-8f5c-44042e68f2cc","control_id":"P-LIT-006","version":1,"effective_from":"2022-12-26","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure system-generated intimations are answered or settled within the prescribed time to avoid GSTR-1 blocking and escalation.","law_refs":["CGST-RULE-88C","CGST-RULE-88D","CGST-RULE-59"],"required_data":["gstr1","gstr3b","gstr2b"],"procedure":"1. List DRC-01B and DRC-01C intimations by period and amount.\\n2. Map each to reconciliation results from B-OUT-002 and C-ITC-001.\\n3. Verify Part B response (payment via DRC-03 or explanation) filed within the prescribed time.\\n4. Check whether GSTR-1 filing was blocked and the impact on customers.","automation":{"type": "GSTR1_GSTR3B", "engine": "recon"},"expected_result":"All intimations answered timely with reconciliations or payments.","exception_conditions":"Unanswered intimations; GSTR-1 blocked; explanation inconsistent with books.","risk_level":"medium","exposure_basis":"Liability/ITC differences with interest; potential demand proceedings; customer ITC delays.","evidence_required":["Intimations","Part B replies","DRC-03"],"corrective_action":"File responses, pay accepted differences with interest, and run monthly pre-filing comparisons.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.746573+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"d8ee781c-bf4a-4c56-bf1d-2794f5904375","control_id":"Q-SPL-001","version":1,"effective_from":"2018-10-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure GST TDS deducted by Government departments, PSUs and notified deductors is accepted on the portal, credited to the cash ledger and reconciled with customer receivables.","law_refs":["CGST-ACT-S51","CGST-ACT-S49"],"required_data":["gstr7_8","receivables_payables","electronic_cash_ledger","sales_register"],"procedure":"1. Download TDS/TCS credit received statements for each period.\\n2. Reconcile TDS amounts with customer receipts and short-payments in receivables (2% of taxable value where contract exceeds Rs 2.5 lakh).\\n3. Verify acceptance of TDS credits and corresponding credit in the electronic cash ledger.\\n4. Identify deductors who deducted but did not file GSTR-7, or reported wrong GSTIN/value.\\n5. Ensure TDS receivable GL is cleared on acceptance.","automation":null,"expected_result":"All TDS credits accepted and reconciled; no stale TDS receivable balances.","exception_conditions":"Credits pending acceptance; deductions in books without portal credit; wrong deductee GSTIN.","risk_level":"low","exposure_basis":"Loss of cash ledger credit and receivable write-off risk equal to unreconciled TDS.","evidence_required":["TDS credit statement","Receivable reconciliation","Cash ledger extract"],"corrective_action":"Accept credits, pursue deductors for corrections, and clear GL balances.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.750307+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"71834dc4-c811-4219-97be-ac6cc34ba255","control_id":"Q-SPL-002","version":1,"effective_from":"2018-10-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["ecommerce"],"objective":"Reconcile marketplace sales, returns and TCS credits reported by e-commerce operators with GSTR-1 and books.","law_refs":["CGST-ACT-S52","CGST-ACT-S37"],"required_data":["gstr7_8","sales_register","gstr1","receivables_payables"],"procedure":"1. Obtain marketplace settlement reports and TCS statements for each ECO and GSTIN (including fulfilment-centre States).\\n2. Reconcile net taxable value per ECO (GSTR-8) with sales net of returns per books and GSTR-1 (Table 14 supplies through ECO).\\n3. Investigate differences: returns timing, cancelled orders, State mapping of fulfilment centres.\\n4. Accept TCS credits and reconcile with receivable from ECO.","automation":null,"expected_result":"ECO-reported values reconcile with GSTR-1; TCS credits accepted.","exception_conditions":"ECO values exceed GSTR-1 (under-reporting risk); sales in States where seller is not registered.","risk_level":"medium","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings. Unregistered-State sales create registration exposure.","evidence_required":["Settlement reports","GSTR-8 credit data","Reconciliation"],"corrective_action":"Correct GSTR-1, pay differential tax with interest, register in fulfilment States, and reconcile monthly.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.754811+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"63f20a20-a6e6-44cc-8faa-9c25f055236d","control_id":"Q-SPL-003","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["ecommerce"],"objective":"Ensure notified services supplied through ECOs (restaurant, passenger transport, accommodation, housekeeping) are taxed by the ECO and not double-taxed or omitted.","law_refs":["CGST-ACT-S9-5","CGST-ACT-S37"],"required_data":["sales_register","gstr1","gstr3b"],"procedure":"1. Identify revenue streams through ECOs and determine whether they fall under Section 9(5).\\n2. For 9(5) supplies, verify the supplier does not pay tax and reports value in the designated tables (GSTR-1 Table 14/GSTR-3B 3.1.1 as applicable).\\n3. Where the company is the ECO, verify tax paid in cash on 9(5) supplies.","automation":null,"expected_result":"Correct liability allocation and reporting.","exception_conditions":"Tax paid by both supplier and ECO; 9(5) supplies omitted.","risk_level":"low","exposure_basis":"Excess tax paid (refund subject to unjust enrichment) or short-paid tax + interest by ECO.","evidence_required":["ECO statements","Return tables"],"corrective_action":"Correct reporting and coordinate with ECO.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.757573+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"fe3d6661-f4c4-4c29-b95a-1ba462716a6b","control_id":"Q-SPL-004","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["works_contract"],"objective":"Verify classification of composite supplies involving immovable property as works contract, the rate entry applied, and that ITC on construction of own immovable property is not claimed.","law_refs":["CGST-ACT-S17-5","NOTIF-11-2017-CTR","JUDG-SAFARI-RETREATS-2024"],"required_data":["sales_register","purchase_register","fixed_asset_register"],"procedure":"1. Identify outward contracts involving construction, installation or erection that result in immovable property.\\n2. Verify the rate entry (including concessional entries for specified recipients) and supporting certificates.\\n3. Identify inward works contract services and goods used for construction of own immovable property and verify ITC reversal under Section 17(5)(c)/(d).\\n4. Distinguish plant and machinery installations (eligible) from civil structures (blocked).","automation":{"key": "WRONG_RATE", "engine": "check"},"expected_result":"Correct classification and rates; ITC blocked on own construction.","exception_conditions":"Concessional rate without eligibility evidence; ITC claimed on building construction.","risk_level":"medium","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings. ITC reversal + interest on blocked construction credit.","evidence_required":["Contracts","Rate entry analysis","Capitalisation details"],"corrective_action":"Correct rates and invoices, reverse blocked ITC, and document plant and machinery positions.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.760101+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"b5700de9-b41c-4f6d-af76-c98d7a0443fc","control_id":"Q-SPL-005","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure mandatory inclusions in transaction value under Section 15(2) are taxed at the rate of the principal supply.","law_refs":["CGST-ACT-S15","CGST-ACT-S15-2","CGST-RULE-33"],"required_data":["sales_register","general_ledger","journal_vouchers"],"procedure":"1. Identify separately recovered charges (freight, packing, insurance, installation, tooling) and verify they are part of taxable value.\\n2. Identify interest/late fee/penalty recovered from customers for delayed payment and verify tax paid.\\n3. Identify subsidies linked to price from non-Government sources.\\n4. Identify tooling/moulds supplied by customers free of cost (amortisation inclusion analysis).","automation":null,"expected_result":"All inclusions taxed.","exception_conditions":"Late-payment interest recovered without tax; freight recovered through debit notes without GST.","risk_level":"medium","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["Recovery ledgers","Customer contracts"],"corrective_action":"Pay tax with interest and configure billing to include ancillary charges in taxable value.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.762501+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"9856f252-47ae-4290-8ad2-5cdf5d1a2935","control_id":"Q-SPL-006","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["related_party"],"objective":"Verify valuation of supplies to related persons and distinct persons under Rule 28, particularly where the recipient is not eligible for full ITC.","law_refs":["CGST-RULE-28","CGST-ACT-SCH1-2","CGST-ACT-S15"],"required_data":["sales_register","customer_master"],"procedure":"1. Identify related-party customers (Section 15 Explanation) from the related-party register.\\n2. Compare prices with those charged to unrelated customers for like goods/services.\\n3. Where the recipient is fully ITC-eligible, document reliance on the second proviso to Rule 28.\\n4. Where the recipient has exempt/blocked use, verify OMV or cost-plus valuation.","automation":null,"expected_result":"Defensible valuation documented for all related-party supplies.","exception_conditions":"Concessional pricing to related parties making exempt supplies; no valuation note.","risk_level":"medium","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["Related-party list","Pricing analysis","Valuation note"],"corrective_action":"Pay differential tax with interest and maintain a valuation policy.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.76492+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"ea7466f7-2abf-4fe0-b2b8-be4b3fe1b8c3","control_id":"Q-SPL-007","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure business transfers are correctly characterised (exempt transfer of going concern vs taxable asset sale) and unutilised ITC is transferred through ITC-02.","law_refs":["NOTIF-12-2017-CTR","CGST-ACT-S18-3","CGST-RULE-41","CGST-ACT-S18-6"],"required_data":["electronic_credit_ledger","fixed_asset_register","general_ledger"],"procedure":"1. Review business transfer agreement/scheme for transfer of business as a going concern (assets, liabilities, employees, contracts) vs itemised asset sale.\\n2. Where going concern, verify exemption applied and documentation.\\n3. Where itemised sale, verify tax on each asset including Section 18(6) computation.\\n4. Verify ITC-02 filed by transferor with CA/CMA certificate and accepted by transferee; verify apportionment where partial transfer (demerger) by asset value.\\n5. Verify registration actions (transferee registration, transferor cancellation/amendment).","automation":null,"expected_result":"Correct characterisation and ITC transfer.","exception_conditions":"Itemised asset sale claimed as going concern; ITC-02 not filed; ITC transferred without accepted ITC-02.","risk_level":"high","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings. Loss of transferable ITC.","evidence_required":["Business transfer agreement","ITC-02 and certificate","Valuation report"],"corrective_action":"File ITC-02, pay tax where transfer is not a going concern, and update registrations.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.767344+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"cca21e48-a4f2-45d3-b662-df78445e66f3","control_id":"Q-SPL-008","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Track two-year limitation for all refund categories (zero-rated, inverted duty, excess cash, wrong head, deemed export, appeal outcomes).","law_refs":["CGST-ACT-S54","CGST-RULE-89","CGST-ACT-S77"],"required_data":["refunds","gstr3b","electronic_cash_ledger"],"procedure":"1. List refund-eligible periods and amounts by category.\\n2. Compute relevant date for each (e.g., due date of return for ITC refunds; date of payment for wrong head; date of appellate order).\\n3. Flag periods within six months of limitation and those already time-barred.\\n4. Verify claims filed and status (RFD-02/03/04/06).","automation":null,"expected_result":"No refunds lapse.","exception_conditions":"Refunds lapsing; deficiency memos not responded to.","risk_level":"medium","exposure_basis":"Lost refund (time-barred) amount.","evidence_required":["Refund tracker","RFD acknowledgements"],"corrective_action":"File claims before limitation and respond to deficiency memos promptly.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.770782+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"fbdb7f89-9b11-41df-bc37-65245b3e4787","control_id":"Q-SPL-009","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Monitor unregistered vendors whose supplies to the company indicate they have crossed registration thresholds, and composition vendors who charge GST on invoices.","law_refs":["CGST-ACT-S22","CGST-ACT-S10","CGST-ACT-S16-2"],"required_data":["vendor_master","purchase_register","gstr2b"],"procedure":"1. Compute cumulative purchases per unregistered vendor (PAN-based) in the financial year.\\n2. Flag vendors whose supplies to the company alone exceed the Section 22 threshold and request registration status.\\n3. Identify composition vendors (taxpayer type) whose invoices show GST and on which ITC was claimed.\\n4. Identify vendors charging GST without registration (no GSTIN or invalid GSTIN).","automation":null,"expected_result":"Vendor base compliant; no ITC from composition or unregistered vendors.","exception_conditions":"ITC on composition-vendor invoices; GST paid to unregistered vendors.","risk_level":"low","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (Rule 88B); penalty exposure u/s 73/74/74A. Tax paid to unregistered vendors is a recoverable (G bucket).","evidence_required":["Vendor purchase analysis","Taxpayer type report"],"corrective_action":"Reverse ineligible ITC, recover tax wrongly charged, and require GST status validation at vendor onboarding.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.774046+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"32f17747-b17b-46ad-a2b7-c74684990935","control_id":"Q-SPL-010","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["ecommerce","works_contract","multi_gstin"],"objective":"Ensure new places of business opened during the period (project sites, fulfilment centres, warehouses) are registered or added before operations commence.","law_refs":["CGST-ACT-S22","CGST-ACT-S25","CGST-ACT-S28","CGST-RULE-19"],"required_data":["eway_bill_register","general_ledger","fixed_asset_register","stock_register"],"procedure":"1. Identify new sites from capex, lease, project contracts and ECO fulfilment-centre reports.\\n2. Compare commencement dates with registration/amendment dates.\\n3. Review e-way bill destinations/dispatch points for undeclared locations.\\n4. Assess State-level registration requirements for project sites in new States.","automation":null,"expected_result":"All new sites registered before operations.","exception_conditions":"Operations or stock at unregistered locations; supplies from a State without registration.","risk_level":"medium","exposure_basis":"Penalty u/s 122/125; tax on supplies made without registration + interest; ITC risk on goods received at unregistered premises.","evidence_required":["New site listing","REG-14/REG-06 copies"],"corrective_action":"Register or add sites, and require tax sign-off in site-opening checklist.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.77936+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"30ad2b68-06aa-401f-a89d-a01a4a3e82e3","control_id":"Q-SPL-011","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure accounts and records are retained for 72 months from the due date of the annual return (longer where proceedings are pending) and electronic records are backed up and retrievable.","law_refs":["CGST-ACT-S35","CGST-ACT-S36","CGST-RULE-56"],"required_data":["general_ledger","purchase_register","sales_register"],"procedure":"1. Review document retention policy against Section 36 requirements.\\n2. Identify the oldest open financial year (considering pending proceedings and limitation).\\n3. Test retrieval of a sample of invoices, e-way bills, contracts and reconciliations for that year.\\n4. Verify backup and access controls over electronic records, including ERP migrations.","automation":null,"expected_result":"Records for all open years retrievable.","exception_conditions":"Records lost on ERP migration; vendor invoices not retrievable for open years.","risk_level":"low","exposure_basis":"Inability to substantiate ITC (burden on taxpayer u/s 155) leading to disallowance; penalty for non-maintenance.","evidence_required":["Retention policy","Retrieval test results"],"corrective_action":"Update retention policy and archive data from legacy systems.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.784828+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"2d49b0fe-fa11-47ff-91df-ff8c9f7c4816","control_id":"Q-SPL-012","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["related_party"],"objective":"Evaluate RCM on secondment arrangements where an overseas group entity seconds employees and the Indian entity reimburses salary costs.","law_refs":["JUDG-NORTHERN-OPERATING-2022","IGST-ACT-S5-3","CGST-ACT-SCH1-4","CIRC-210-04-2024"],"required_data":["general_ledger","bank_payments","journal_vouchers"],"procedure":"1. Identify seconded employees from payroll/HR records and intercompany reimbursements.\\n2. Review secondment agreements for control, employer of record, and reimbursement terms.\\n3. Apply the Northern Operating Systems principles to determine whether a supply of manpower by the overseas entity exists.\\n4. Compute IGST RCM on reimbursements (value per invoice where fully ITC-eligible per Circular 210/4/2024-GST) and verify payment and ITC.\\n5. Consider limitation and any pending notices on the issue.","automation":{"key": "RCM_IMPORT_OF_SERVICES", "engine": "check"},"expected_result":"RCM evaluated and paid where applicable.","exception_conditions":"Salary reimbursements to overseas entity without RCM.","risk_level":"medium","exposure_basis":"IGST RCM + interest u/s 50(1); ITC generally available, so cash-flow/interest exposure primarily.","evidence_required":["Secondment agreements","Reimbursement records","RCM computation"],"corrective_action":"Pay RCM with interest and claim ITC; restructure secondment documentation.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.788386+00:00"}') on conflict do nothing;
