insert into public.observation_templates select * from json_populate_record(null::public.observation_templates, E'{"id":"564bbeac-9b62-45e0-82c3-d7996126ced0","organisation_id":"ab1e43f8-6f0f-47de-a67d-c98a9e496a44","module":"B","control_id":"B-OUT-002","category":"Output Liability","title":"Tax declared in GSTR-1 not fully discharged in GSTR-3B","observation_text":"For {{period}}, output tax declared in GSTR-1 exceeds the liability discharged in GSTR-3B by {{amount}} ({{tax_head_breakup}}). The difference arises mainly from {{root_cause}} and has not been paid in subsequent returns or through DRC-03.","legal_framework":"• Section 39 — tax payable as per return must be paid by the due date of the return\\n• Section 50(1) — interest @ 18% p.a. on delayed payment of tax\\n• Rule 88C — system intimation in DRC-01B for GSTR-1 vs GSTR-3B differences; non-response blocks GSTR-1","legal_reference_codes":["CGST-ACT-S39","CGST-ACT-S50-1","CGST-RULE-88C"],"action_required":"1. Validate the document-level reconciliation and confirm the net shortfall.\\n2. Pay the shortfall of {{amount}} with interest through DRC-03 citing ''voluntary''.\\n3. Respond to any DRC-01B intimation in Part B with the reconciliation.","preventive_control":"Monthly pre-filing comparison of GSTR-1 and GSTR-3B liability by head, with sign-off before filing GSTR-3B.","risk_grade":"critical","impact_bucket":"D_OTHER_LIABILITY","industries":[],"tags":["gstr1","gstr3b","liability","interest"],"is_approved":true,"created_by":null,"created_at":"2026-10-24T13:42:08.794893+00:00"}') on conflict do nothing;
insert into public.observation_templates select * from json_populate_record(null::public.observation_templates, E'{"id":"4525d186-a084-4174-a704-77087b60638b","organisation_id":"ab1e43f8-6f0f-47de-a67d-c98a9e496a44","module":"B","control_id":"B-OUT-001","category":"Outward Reporting","title":"Invoices recorded in books not reported in GSTR-1","observation_text":"{{count}} invoices aggregating taxable value {{taxable_value}} and tax {{amount}} recorded in the sales register for {{period}} were not reported in GSTR-1. Sample: invoice {{voucher_no}} dated {{date}} to {{customer_gstin}}.","legal_framework":"• Section 37 — details of all outward supplies to be furnished in GSTR-1 for the tax period\\n• Section 35 — accounts to reflect true and correct outward supplies","legal_reference_codes":["CGST-ACT-S37","CGST-ACT-S35"],"action_required":"1. Report the invoices in the next GSTR-1/GSTR-1A within the time limit.\\n2. Where tax was not paid in GSTR-3B, pay with interest.\\n3. Inform affected customers regarding ITC timing.","preventive_control":"Automated books-to-GSTR-1 reconciliation at document level before each GSTR-1 filing.","risk_grade":"high","impact_bucket":"D_OTHER_LIABILITY","industries":[],"tags":["gstr1","reconciliation"],"is_approved":true,"created_by":null,"created_at":"2026-10-24T13:42:08.797444+00:00"}') on conflict do nothing;
insert into public.observation_templates select * from json_populate_record(null::public.observation_templates, E'{"id":"9597086c-7f99-410a-95c8-bc0abca134c7","organisation_id":"ab1e43f8-6f0f-47de-a67d-c98a9e496a44","module":"B","control_id":"B-OUT-008","category":"Credit Notes","title":"GST reduced on credit notes not meeting Section 15(3)/34 conditions","observation_text":"Credit notes aggregating {{amount}} of GST were issued towards {{discount_type}} (e.g., credit note {{voucher_no}} dated {{date}}). These discounts were not established through an agreement entered into before or at the time of supply and/or evidence of recipient ITC reversal is not available.","legal_framework":"• Section 15(3)(b) — post-supply discount excludable only if pre-agreed, linked to invoices and ITC reversed by recipient\\n• Section 34 — credit note permitted only for specified situations\\n• Circular No. 212/6/2024-GST — mechanism to evidence recipient''s ITC reversal","legal_reference_codes":["CGST-ACT-S15-3","CGST-ACT-S34","CIRC-212-06-2024"],"action_required":"1. Pay GST of {{amount}} with interest on non-qualifying credit notes.\\n2. Obtain recipient/CA certificates for qualifying credit notes.\\n3. Convert future ad hoc settlements to financial credit notes without GST.","preventive_control":"Credit note approval workflow requiring scheme reference, invoice linkage and recipient reversal evidence before GST credit notes are issued.","risk_grade":"high","impact_bucket":"C_CREDIT_NOTE","industries":[],"tags":["credit-note","discount","section-34"],"is_approved":true,"created_by":null,"created_at":"2026-10-24T13:42:08.799132+00:00"}') on conflict do nothing;
insert into public.observation_templates select * from json_populate_record(null::public.observation_templates, E'{"id":"e52efc76-ce03-408b-a65b-60423f657673","organisation_id":"ab1e43f8-6f0f-47de-a67d-c98a9e496a44","module":"B","control_id":"B-OUT-006","category":"Credit Notes","title":"Credit notes issued after the Section 34(2) time limit","observation_text":"{{count}} credit notes relating to supplies of FY {{fy}} were declared after 30 November {{year}} and output tax of {{amount}} was reduced.","legal_framework":"• Section 34(2) — credit note to be declared not later than 30 November following the end of the FY of supply or the date of annual return, whichever is earlier","legal_reference_codes":["CGST-ACT-S34"],"action_required":"1. Reverse the tax reduction by paying {{amount}} with interest.\\n2. Treat the credit notes as financial credit notes for GST purposes.","preventive_control":"ERP validation blocking GST credit notes against invoices of a prior FY after the statutory cut-off.","risk_grade":"high","impact_bucket":"C_CREDIT_NOTE","industries":[],"tags":["credit-note","time-limit"],"is_approved":true,"created_by":null,"created_at":"2026-10-24T13:42:08.801609+00:00"}') on conflict do nothing;
insert into public.observation_templates select * from json_populate_record(null::public.observation_templates, E'{"id":"21062bf2-bbc6-4026-8c67-91be16ffd7aa","organisation_id":"ab1e43f8-6f0f-47de-a67d-c98a9e496a44","module":"B","control_id":"B-OUT-009","category":"Free Supplies","title":"Free-of-cost supplies to related/distinct persons without tax","observation_text":"Goods valued at {{amount}} were supplied free of cost to {{related_party}} (a related/distinct person) during {{period}} without issuing a tax invoice.","legal_framework":"• Schedule I, Para 2 — supplies between related/distinct persons are taxable even without consideration\\n• Rule 28 — valuation at open market value or as prescribed\\n• Circular No. 92/11/2019-GST — treatment of free samples and gifts","legal_reference_codes":["CGST-ACT-SCH1-2","CGST-RULE-28","CIRC-92-11-2019"],"action_required":"1. Issue tax invoices and pay tax with interest on the Rule 28 value.\\n2. Where recipient is eligible for full ITC, document invoice value as deemed open market value.","preventive_control":"Separate ERP movement types for FOC/related-party issues with automatic tax determination.","risk_grade":"medium","impact_bucket":"D_OTHER_LIABILITY","industries":[],"tags":["foc","schedule-i","valuation"],"is_approved":true,"created_by":null,"created_at":"2026-10-24T13:42:08.805423+00:00"}') on conflict do nothing;
insert into public.observation_templates select * from json_populate_record(null::public.observation_templates, E'{"id":"437ff554-6c3c-46e6-9ce5-c8475f89fd5e","organisation_id":"ab1e43f8-6f0f-47de-a67d-c98a9e496a44","module":"B","control_id":"B-OUT-005","category":"Place of Supply","title":"Incorrect tax head charged (CGST+SGST instead of IGST)","observation_text":"Invoices aggregating {{amount}} of tax for supplies with place of supply in {{pos_state}} (including supplies to SEZ units) were charged CGST+SGST instead of IGST.","legal_framework":"• IGST Act Section 7(5) — supplies to SEZ are inter-State\\n• IGST Act Section 10/12 — place of supply rules\\n• Section 77 CGST / Section 19 IGST — refund of tax paid under wrong head; no interest on correct head","legal_reference_codes":["IGST-ACT-S7-5","IGST-ACT-S10","CGST-ACT-S77","IGST-ACT-S19"],"action_required":"1. Pay IGST of {{amount}} under the correct head.\\n2. Claim refund of CGST/SGST paid under the wrong head within two years.\\n3. Coordinate with customers for ITC correction.","preventive_control":"POS determination logic in tax engine based on ship-to State and SEZ flag in customer master.","risk_grade":"high","impact_bucket":"G_RECOVERABLE","industries":[],"tags":["pos","igst","sez"],"is_approved":true,"created_by":null,"created_at":"2026-10-24T13:42:08.807302+00:00"}') on conflict do nothing;
insert into public.observation_templates select * from json_populate_record(null::public.observation_templates, E'{"id":"eef1153e-3ff6-4566-8cf8-48d90ac9f35f","organisation_id":"ab1e43f8-6f0f-47de-a67d-c98a9e496a44","module":"C","control_id":"C-ITC-001","category":"ITC Mismatch","title":"ITC availed in excess of GSTR-2B","observation_text":"ITC availed in GSTR-3B for {{period}} exceeds ITC available in GSTR-2B by {{amount}}. {{count}} invoices from {{vendor_count}} vendors are not reflected in GSTR-2B (e.g., vendor {{vendor_gstin}}, invoice {{voucher_no}}).","legal_framework":"• Section 16(2)(aa) — ITC only on invoices furnished by supplier and communicated to recipient\\n• Rule 36(4) — ITC restricted to GSTR-2B\\n• Section 50(3) read with Rule 88B — interest on ITC wrongly availed and utilised","legal_reference_codes":["CGST-ACT-S16-2-AA","CGST-RULE-36-4","CGST-ACT-S50-3","CGST-RULE-88B"],"action_required":"1. Reverse ITC of {{amount}} in GSTR-3B Table 4(B)(2).\\n2. Follow up vendors to report invoices; re-claim when reflected in GSTR-2B within the Section 16(4) time limit.\\n3. Compute and pay interest to the extent the credit was utilised.","preventive_control":"Monthly PR-2B-3B reconciliation with vendor follow-up and ITC claim restricted to matched invoices.","risk_grade":"critical","impact_bucket":"A_ITC_REVERSAL","industries":[],"tags":["itc","gstr2b","reconciliation"],"is_approved":true,"created_by":null,"created_at":"2026-10-24T13:42:08.811027+00:00"}') on conflict do nothing;
insert into public.observation_templates select * from json_populate_record(null::public.observation_templates, E'{"id":"d370d33f-6282-4e98-95e2-952dab9ae406","organisation_id":"ab1e43f8-6f0f-47de-a67d-c98a9e496a44","module":"C","control_id":"C-ITC-001","category":"ITC Opportunity","title":"Eligible ITC in GSTR-2B not availed","observation_text":"ITC of {{amount}} appearing in GSTR-2B for {{period}} relating to eligible business purchases has not been availed in GSTR-3B.","legal_framework":"• Section 16(1) — entitlement to ITC on business inputs\\n• Section 16(4) — ITC to be availed by 30 November following the end of the FY or date of annual return, whichever earlier","legal_reference_codes":["CGST-ACT-S16-1","CGST-ACT-S16-4"],"action_required":"1. Book the invoices and claim ITC in the next GSTR-3B, before the Section 16(4) cut-off.\\n2. Confirm eligibility (not blocked, used for taxable supplies).","preventive_control":"Monthly review of 2B-only items with procurement.","risk_grade":"opportunity","impact_bucket":"E_ITC_REAVAILABLE","industries":[],"tags":["itc","opportunity"],"is_approved":true,"created_by":null,"created_at":"2026-10-24T13:42:08.813188+00:00"}') on conflict do nothing;
insert into public.observation_templates select * from json_populate_record(null::public.observation_templates, E'{"id":"24e04879-04bd-4ac8-8332-eb4e06987187","organisation_id":"ab1e43f8-6f0f-47de-a67d-c98a9e496a44","module":"C","control_id":"C-ITC-003","category":"ITC Time Limit","title":"ITC availed after Section 16(4) time limit","observation_text":"ITC of {{amount}} relating to invoices of FY {{fy}} was availed in GSTR-3B for {{period}} filed on {{date}}, after the Section 16(4) time limit.","legal_framework":"• Section 16(4) — ITC cannot be availed after 30 November following the end of the FY or the date of filing annual return, whichever earlier (as amended w.e.f. 01.10.2022)","legal_reference_codes":["CGST-ACT-S16-4"],"action_required":"1. Reverse the time-barred ITC of {{amount}}.\\n2. Pay interest u/s 50(3) to the extent utilised.\\n3. Charge the tax to the profit and loss account.","preventive_control":"Year-end ITC sweep by the October return and system block on ITC for prior-year invoices after the cut-off.","risk_grade":"high","impact_bucket":"A_ITC_REVERSAL","industries":[],"tags":["itc","time-bar"],"is_approved":true,"created_by":null,"created_at":"2026-10-24T13:42:08.815507+00:00"}') on conflict do nothing;
