insert into public.observation_templates select * from json_populate_record(null::public.observation_templates, E'{"id":"ba7ff36d-8fe2-4cb4-9e87-a6ff5472e947","organisation_id":"ab1e43f8-6f0f-47de-a67d-c98a9e496a44","module":"C","control_id":"C-ITC-006","category":"ITC Reversal","title":"ITC not reversed on payables outstanding beyond 180 days","observation_text":"Vendor invoices with tax of {{amount}} remained unpaid beyond 180 days as at {{date}}, but ITC was not reversed.","legal_framework":"• Section 16(2) second proviso and Rule 37 — reversal of ITC where payment not made within 180 days; re-availment on payment","legal_reference_codes":["CGST-ACT-S16-2","CGST-RULE-37","CIRC-170-02-2022"],"action_required":"1. Reverse ITC in Table 4(B)(2).\\n2. Re-claim in Table 4(A)(5) upon payment.\\n3. Pay interest where utilised.","preventive_control":"Monthly 180-day AP ageing report linked to GST reversal.","risk_grade":"medium","impact_bucket":"E_ITC_REAVAILABLE","industries":[],"tags":["rule-37","payables"],"is_approved":true,"created_by":null,"created_at":"2026-10-24T13:42:08.820521+00:00"}') on conflict do nothing;
